        // Verify the minted tokens weren't allocated to regular balances
        assertEq(
            token.balanceOf(address(this)),
            0,
            "Test contract received tokens unexpectedly"
        );
        assertEq(
            token.balanceOf(address(token)),
            0,
            "Token contract holds tokens unexpectedly"
        );
    }
}
